INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch10$PT141-S2-Q4$batch10$, 141, 2, 4, $batch10$Principle-Conform$batch10$, $batch10$Principle: The executive in a given company whose compensation package is determined by advice of an external consultant is likely to be overcompensated if the consultant also has business interests with the company the executive manages.$batch10$, $batch10$Which one of the following judgments conforms most closely to the principle stated above?$batch10$, $batch10$D$batch10$, true, $batch10$Batch 10; question text from local bank.$batch10$ FROM lr_sections s WHERE s.preptest=141 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT141-S2-Q4$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$A$batch10$, $batch10$The president of the Troskco Corporation is definitely overpaid, since he receives in salary and benefits almost 40 times more than the average employee of Troskco receives.$batch10$, $batch10$No Trigger$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT141-S2-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$A$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$B$batch10$, $batch10$The president of the Troskco Corporation is probably overpaid, since his total annual compensation package was determined five years ago, when the company’s profits were at an all-time high.$batch10$, $batch10$No Trigger$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT141-S2-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$B$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$C$batch10$, $batch10$The president of the Troskco Corporation is probably not overpaid, since his total compensation package was determined by the Troskco board of directors without retaining the services of an external compensation consultant.$batch10$, $batch10$Illegal Negation$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT141-S2-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$C$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$D$batch10$, $batch10$The president of Troskco Corporation is probably overpaid, since the Troskco board of directors determined his compensation by following the advice of an external consultant who has many other contracts with Troskco.$batch10$, $batch10$Correct$batch10$, true FROM lr_questions q WHERE q.qid=$batch10$PT141-S2-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$D$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$E$batch10$, $batch10$The president of Troskco Corporation is definitely not overpaid, since the external consultant the board of directors retained to advise on executive salaries has no other contracts with Troskco.$batch10$, $batch10$Illegal Negation$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT141-S2-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$E$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT141-S2-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Rule$batch10$, $batch10$If an executive's compensation is set by the advice of an outside consultant, and that consultant also has business interests with the company, the executive is likely overcompensated.$batch10$), (1, $batch10$Evaluate$batch10$, $batch10$The rule has two triggers that must both be present: the pay was set on an outside consultant's advice, and that consultant has other business with the company. The outcome is "likely" overcompensated, not "definitely." The rule says nothing about cases where a trigger is missing.$batch10$), (2, $batch10$Goal$batch10$, $batch10$A judgment that an executive is probably overpaid because the pay was set by an outside consultant who has other business with the company.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT141-S2-Q4$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$There's no consultant here, just a comparison with average pay. And "definitely" overstates the rule's "likely."$batch10$), ($batch10$B$batch10$, $batch10$Pay set during a profitable year has nothing to do with an outside consultant with ties to the company.$batch10$), ($batch10$C$batch10$, $batch10$No outside consultant means the rule's trigger is missing. The rule then tells us nothing, so it can't support "probably not overpaid."$batch10$), ($batch10$D$batch10$, $batch10$The board followed an outside consultant's advice, and that consultant has many other contracts with Troskco. Both triggers are present, and "probably overpaid" matches the rule's "likely."$batch10$), ($batch10$E$batch10$, $batch10$The consultant has no other contracts, so one trigger fails and the rule says nothing. "Definitely not overpaid" also goes far beyond anything the rule could support.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT141-S2-Q4$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
